behavior('B-phase1','A1','handlePropose/startPhase1 or received PreAccept and PreAcceptReply',['S-preaccept','S-attrs','S-send','S-base'],writes=['Proposer allocates local row slot, derives conflicts and initial attributes, initializes leader bookkeeping and broadcasts to FastQuorumSize()-1 peers in thrifty mode.','Receiver rejects lower ballot; otherwise advances bal and computes attributes only below ACCEPTED. Existing accepted-or-later records retain attributes.','Replies of lastTriedBallot increment preAcceptOKs; merge attributes except local replica coordinate. Initial ballot, allEqual and (for N>7) committed dependencies permit fast commit; otherwise enough replies trigger Accept.'],important_branches=['N<=3 and Thrifty bypass reply attribute equality requirement.','For accepted-or-later records missing commands, PreAccept fills the LeaderId row rather than Replica row.','Leader bookkeeping seq starts at -1 and ballot at -1; reply VBallot can replace attributes and status.'],produces_fact_ids=['F-record','F-decision'],consumes_fact_ids=['F-record'],existing_protections=['Lower ballot PreAccept rejected; stale replies rejected; bookkeeping phase guard.'],unknowns=['Does quorum sizing and attribute merging preserve required support across permitted N and recovery ownership?'])
behavior('B-accept','A1','Accept request or AcceptReply delivery',['S-accept','S-send','S-types'],writes=['Receiver creates NONE record if absent; for nonstale and not committed records installs Seq, Deps, bal and vbal but does not assign Status or Cmds.','Leader counts replies matching lastTriedBallot while lb.status is ACCEPTED; acceptOKs+1>N/2 sets local COMMITTED and broadcasts Commit.'],external_effects=['Receiver replies with current bal after all branches; leader may reply to clients if Dreply is false.'],produces_fact_ids=['F-record','F-decision'],consumes_fact_ids=['F-record'],existing_protections=['Stale Accept cannot replace attributes; committed/executed record protected.'],unknowns=['What recovery guarantee is established by an acknowledgement whose stored Status remains preaccepted or NONE?','Higher-ballot AcceptReply retry block follows a != ballot return and appears unreachable.'])
behavior('B-authority','A2','BeTheLeader; startRecoveryForInstance; Prepare delivery',['S-ballot','S-recovery','S-commit'],writes=['BeTheLeader sets IsLeader true; no revocation in this handler.','Recovery preserves client proposals but replaces bookkeeping, copies current value information, chooses lastTriedBallot, and changes both local bal and vbal to that ballot before adding self PrepareReply.','Prepare raises bal on a higher ballot while retaining vbal, Cmds, Seq, Deps and Status for its reply.'],external_effects=['Recovery sends Prepare to alive peers; Prepare replies report current stored record.'],produces_fact_ids=['F-record'],consumes_fact_ids=['F-record'],cross_activity_effects={'A1':'The ballot promise rejects older formation requests; the separate value ballot and status feed recovery selection.'},unknowns=['Recovery initiation changes vbal unlike received Prepare; whether it can hide a higher-priority prior accepted value needs legal-history investigation.'])
