behavior('B-commit','A1','Commit receipt',['S-commit','S-attrs'],writes=['Creates missing record; rejects if already committed/executed or if commit ballot is below bal. Otherwise installs command/attributes and COMMITTED, updates conflicts and committed prefix.'],produces_fact_ids=['F-record','F-decision'],consumes_fact_ids=['F-record'],external_effects=['A NOOP commit for own row can requeue client proposals; persistence calls here do not sync.'])
